<script>
(function () {
    const collection = document.getElementById('clientServicesCollection');
    const controls = document.querySelectorAll('#client-services [data-services-view]');
    if (!collection || controls.length !== 2) return;

    const storageKey = 'nodexa.client.services.view.v1.{{ (int) $user->id }}';
    function selectView(view, save) {
        if (view !== 'list' && view !== 'grid') return;
        collection.dataset.view = view;
        controls.forEach(function (control) {
            const selected = control.dataset.servicesView === view;
            control.classList.toggle('is-active', selected);
            control.setAttribute('aria-pressed', selected ? 'true' : 'false');
        });
        if (save) {
            try { window.localStorage.setItem(storageKey, view); } catch (_error) {}
        }
    }

    try {
        selectView(window.localStorage.getItem(storageKey) === 'grid' ? 'grid' : 'list', false);
    } catch (_error) {
        selectView('list', false);
    }

    controls.forEach(function (control) {
        control.addEventListener('click', function () {
            selectView(control.dataset.servicesView, true);
        });
    });
})();
</script>
